<?php
 require_once(__DIR__ . '/../init.php'); class system_avest { const TASK_NAME = 'system_avest'; public function getCode($params) { $this->log('state ' . $params['state'], 0); $this->log('code ' . $params['code'], 0); } public function getExecute($params) { $this->log('state ' . $params['state'], 1); $this->log('execute ' . $params['execute'], 1); } public function getError($params) { $this->log('state ' . $params['state'], 2); $this->log('error ' . $params['error'], 2); $this->log('error_description ' . $params['error_description'], 2); } public function getToken($params) { $this->log('state ' . $params['state'], 0); $this->log('access_token ' . $params['access_token'], 0); $this->log('expires_in ' . $params['expires_in'], 0); $this->log('token_type ' . $params['token_type'], 0); } public function log($message, $type = 0) { app_log($message, $type, self::TASK_NAME); } } if ($_GET) { $service = new system_avest(); $service->log (json_encode($_GET), 0); if (isset($_GET['code'])) { $service->getCode($_GET); } else if (isset($_GET['execute'])) { $service->getExecute($_GET); } else if (isset($_GET['error'])) { $service->getError($_GET); } else if (isset($_GET['access_token'])) { $service->getToken($_GET); } } 